mapper.select:
SELECT * FROM post
WHERE community_id = #{communityId}

    AND (created_at < #{lastCreateTime}
         OR (created_at = #{lastCreateTime} AND id < #{lastId}))

ORDER BY created_at DESC, id DESC
LIMIT #{pageSize}

SELECT id, community_id, author_id, title, content, latitude, longitude, geohash,
       created_at AS create_time, updated_at AS update_time
FROM post
WHERE geohash >= #{geohashStart}
  AND geohash < #{geohashEnd}

    AND (created_at < #{lastCreateTime}
         OR (created_at = #{lastCreateTime} AND id < #{lastId}))

ORDER BY created_at DESC, id DESC
LIMIT #{pageSize}
